create extension if not exists "uuid-ossp";
create table if not exists problems (id uuid primary key default uuid_generate_v4(),user_id uuid references auth.users on delete cascade not null,name text not null,platform text not null check(platform in ('LeetCode','Codeforces','CodeChef')),difficulty text check(difficulty in ('Easy','Medium','Hard')),topic text,subtopic text,pattern text,url text,solved_date date not null,created_at timestamptz default now());
create table if not exists revisions (id uuid primary key default uuid_generate_v4(),problem_id uuid references problems on delete cascade not null,user_id uuid references auth.users on delete cascade not null,revision_number int not null check(revision_number between 1 and 10),due_date date not null,status text default 'pending' check(status in ('pending','completed','overdue')),score int check(score between 0 and 100),time_taken int,time_complexity text,space_complexity text,attempts int default 1,completed_date date,recommended_problem_name text,recommended_problem_url text,created_at timestamptz default now(),unique(problem_id,revision_number));
create table if not exists memory_strength (id uuid primary key default uuid_generate_v4(),user_id uuid references auth.users on delete cascade not null,topic text not null,strength_score float default 0,revision_count int default 0,success_rate float default 0,avg_score float default 0,last_revision_date date,next_revision_date date,updated_at timestamptz default now(),unique(user_id,topic));
create table if not exists problem_queue (id uuid primary key default uuid_generate_v4(),user_id uuid references auth.users on delete cascade not null,revision_id uuid references revisions,problem_name text not null,platform text,topic text,subtopic text,difficulty text,url text,status text default 'pending' check(status in ('pending','completed','skipped')),assigned_date date default current_date,due_date date,created_at timestamptz default now());
alter table problems enable row level security;alter table revisions enable row level security;alter table memory_strength enable row level security;alter table problem_queue enable row level security;
create policy "own_problems" on problems for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own_revisions" on revisions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own_memory" on memory_strength for all using(auth.uid()=user_id) with check(auth.uid()=user_id);create policy "own_queue" on problem_queue for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create index if not exists idx_revisions_due on revisions(user_id,due_date,status);create index if not exists idx_problems_user on problems(user_id);create index if not exists idx_memory_topic on memory_strength(user_id,topic);
